import json, os, re
from collections import Counter

base = '/hpc/compgen/projects/llm_GEO_project/harmonia_metadata_agent/analysis/dstoker/harmonia/results'
error_types = Counter()

for root, dirs, files in os.walk(base):
    for f in files:
        if f == 'trace.json':
            filepath = os.path.join(root, f)
            try:
                data = json.load(open(filepath))
                model = data.get('llm', {}).get('model', 'unknown')
                dirname = os.path.basename(os.path.dirname(filepath))

                for turn in data.get('turns', []):
                    for msg in turn.get('raw_messages', []):
                        content = msg.get('content', {})
                        if isinstance(content, dict):
                            text = content.get('text', '')
                            if 'LLM Error' in text:
                                # Categorize the error
                                if 'maximum context length' in text:
                                    error_types['context_length_exceeded (OpenRouter)'] += 1
                                elif 'context_length_exceeded' in text:
                                    error_types['context_length_exceeded (other)'] += 1
                                elif 'truncat' in text.lower():
                                    error_types['truncation'] += 1
                                else:
                                    # Extract the first 200 chars of the error
                                    err_preview = text[:200].replace('\\n', ' ').strip()
                                    error_types[f'{model}: {err_preview}'] += 1
            except Exception as e:
                pass

print('Error type counts across all trace.json files:')
for err, count in error_types.most_common():
    print(f'  [{count}x] {err[:150]}')
